"""Rebuild synthetic-v1-target34.apk (needs a JDK for keytool and jarsigner).

    PYTHONPATH=src:. python tests/fixtures/apk/make_synthetic.py

A release-mistakes build: v1 signature only while targeting Android 14, cleartext HTTP
allowed, sensitive permissions. Generated by us, so it can live in the repository.
"""

from __future__ import annotations

import subprocess
import tempfile
import zipfile
from pathlib import Path

from tests.axml_writer import Node, encode

HERE = Path(__file__).parent
OUT = HERE / "synthetic-v1-target34.apk"

manifest = Node(
    "manifest",
    {"package": "com.qulbot.sample", "versionCode": 42, "versionName": "2.1.0"},
    [
        Node("uses-sdk", {"minSdkVersion": 24, "targetSdkVersion": 34}),
        Node("uses-permission", {"name": "android.permission.INTERNET"}),
        Node("uses-permission", {"name": "android.permission.CAMERA"}),
        Node("uses-permission", {"name": "android.permission.ACCESS_FINE_LOCATION"}),
        Node("application", {"label": "Qul Sample", "usesCleartextTraffic": True}),
    ],
)

with tempfile.TemporaryDirectory() as tmp:
    unsigned = Path(tmp) / "unsigned.apk"
    with zipfile.ZipFile(unsigned, "w", zipfile.ZIP_DEFLATED) as archive:
        archive.writestr("AndroidManifest.xml", encode(manifest))
        archive.writestr("classes.dex", b"dex\n035\x00")
        archive.writestr("lib/arm64-v8a/libsample.so", b"\x7fELF")
    keystore = Path(tmp) / "test.jks"
    subprocess.run(
        ["keytool", "-genkeypair", "-keystore", str(keystore), "-storepass", "qultest",
         "-keypass", "qultest", "-alias", "qul", "-keyalg", "RSA", "-keysize", "2048",
         "-validity", "20000", "-dname", "CN=Qul Test Release, O=Qul Bot"],
        check=True, capture_output=True,
    )  # fmt: skip
    subprocess.run(
        ["jarsigner", "-keystore", str(keystore), "-storepass", "qultest",
         "-signedjar", str(OUT), str(unsigned), "qul"],
        check=True, capture_output=True,
    )  # fmt: skip
print(f"wrote {OUT}")
